--
-- Table structure for table `ea_members`
--

DROP TABLE IF EXISTS `ea_members`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ea_members` (
  `id` int NOT NULL AUTO_INCREMENT,
  `create_times` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '创建时间',
  `gsname` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '公司名称',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '姓名',
  `create_time` int DEFAULT NULL COMMENT '创建时间',
  `status1` int DEFAULT '0' COMMENT '1审核中 2 通过  3 拒绝',
  `status` tinyint(1) DEFAULT '1' COMMENT '0禁用 1 启用',
  `sex` int DEFAULT '1' COMMENT '1 男  2 女',
  `phone` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '手机号码',
  `type` tinyint(1) DEFAULT '0' COMMENT '0 普通用户 1 师傅  ',
  `passwords` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '原始密码',
  `password` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '加密密码',
  `email` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `login` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '账号',
  `liyou` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '拒绝理由',
  `time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '当月时间',
  `jiaru` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT '加入的理由',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=202 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=DYNAMIC COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ea_members`
--

LOCK TABLES `ea_members` WRITE;
/*!40000 ALTER TABLE `ea_members` DISABLE KEYS */;
