--
-- Table structure for table `ea_shebei`
--

DROP TABLE IF EXISTS `ea_shebei`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ea_shebei` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uid` int DEFAULT NULL COMMENT '供应商ID',
  `pinpai` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '设备品牌',
  `jingdu` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '精度',
  `jizhou` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '几轴',
  `gongshi` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '工时',
  `guige` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '设备规格',
  `guigex` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '规格X',
  `channeng` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT '产能',
  `guigey` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '规格Y',
  `guigez` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '规格Z',
  `create_time` datetime DEFAULT NULL,
  `create_times` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `gmtime` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '购买时间',
  `zhuyaohangye` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT '主要行业',
  `status` int DEFAULT '1' COMMENT '1 待审核  2 通过  3 失败',
  `bizhong` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '币种',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `member_id` (`uid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1986 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=DYNAMIC COMMENT='设备管理表';
/*!40101 SET character_set_client = @saved_cs_client */;

