--
-- Table structure for table `fa_cart`
--

DROP TABLE IF EXISTS `fa_cart`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fa_cart` (
  `id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL COMMENT '会员ID',
  `quotation_id` int NOT NULL COMMENT '报价单ID',
  `supplier_id` int NOT NULL COMMENT '供应商ID',
  `equipment_id` int NOT NULL COMMENT '主设备ID',
  `equipment_id2` int DEFAULT '0' COMMENT '辅助设备ID',
  `area_id` int NOT NULL COMMENT '区域ID',
  `strategy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报价策略',
  `price` decimal(10,2) NOT NULL COMMENT '报价金额',
  `type` tinyint(1) DEFAULT '1' COMMENT '洽谈类型:1=供应商洽谈,2=平台洽谈',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态:1=正常,0=删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_member_id` (`member_id`) USING BTREE,
  KEY `idx_quotation_id` (`quotation_id`) USING BTREE,
  KEY `idx_supplier_id` (`supplier_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_area_id` (`area_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='购物车表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `fa_cart`
--

