DROP TABLE IF EXISTS `fa_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fa_order` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `user_id` int NOT NULL COMMENT '用户ID',
  `supplier_id` int NOT NULL COMMENT '供应商ID',
  `quotation_id` int NOT NULL COMMENT '报价单ID',
  `equipment_id` int NOT NULL COMMENT '主设备ID',
  `equipment_id2` int DEFAULT '0' COMMENT '辅助设备ID',
  `area_id` int NOT NULL COMMENT '区域ID',
  `strategy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报价策略',
  `quantity` int DEFAULT '1' COMMENT '采购数量',
  `original_price` decimal(10,2) DEFAULT '0.00' COMMENT '原始报价',
  `counter_price` decimal(10,2) DEFAULT NULL COMMENT '供应商/平台还价',
  `user_price` decimal(10,2) DEFAULT '0.00' COMMENT '用户还价',
  `final_price` decimal(10,2) DEFAULT NULL COMMENT '最终价格',
  `negotiation_type` tinyint(1) DEFAULT '1' COMMENT '洽谈类型:1=供应商洽谈,2=平台洽谈',
  `negotiation_status` tinyint(1) DEFAULT '1' COMMENT '洽谈状态:1=待报价,2=已还价,3=已接受,4=已拒绝',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '拒绝原因',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态:1=待付款,2=待发货,3=待收货,4=已完成,5=已取消',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_order_no` (`order_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_supplier_id` (`supplier_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_area_id` (`area_id`) USING BTREE,
  KEY `idx_quotation_id` (`quotation_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单表';
