DROP TABLE IF EXISTS `fa_order_negotiation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fa_order_negotiation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL COMMENT '订单ID',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '报价金额',
  `type` tinyint NOT NULL DEFAULT '0' COMMENT '操作内容 1=还价',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注说明',
  `operator_id` int NOT NULL DEFAULT '0' COMMENT '具体操作人',
  `operator_type` tinyint(1) DEFAULT '1' COMMENT '操作方:1=供应商/平台,2=用户',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单洽谈记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

