--
-- Table structure for table `fa_quotation`
--

DROP TABLE IF EXISTS `fa_quotation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fa_quotation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_id` int NOT NULL DEFAULT '0' COMMENT '算费任务ID',
  `member_id` int DEFAULT NULL COMMENT '会员ID',
  `area_id` int DEFAULT '0' COMMENT '区域ID',
  `strategy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报价策略',
  `category_id` int NOT NULL COMMENT '分类ID',
  `file_3d_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '3D文件ID',
  `file_2d_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '2D文件ID',
  `material_id` int NOT NULL COMMENT '材料ID',
  `surface_treatment_id` int DEFAULT '0' COMMENT '表面处理ID',
  `heat_treatment_id` int DEFAULT '0' COMMENT '热处理ID',
  `roughness` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '粗糙度',
  `tolerance` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公差带',
  `purchase_quantity` int NOT NULL COMMENT '采购量',
  `annual_quantity` int DEFAULT '0' COMMENT '年用量',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `calculation_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '计算结果数据(JSON)',
  `supplier_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '供应商列表数据(JSON)',
  `min_price` decimal(10,2) DEFAULT '0.00' COMMENT '最低价格',
  `max_price` decimal(10,2) DEFAULT '0.00' COMMENT '最高价格',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'CNY' COMMENT '币种',
  `preview_image` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '预览图片地址',
  `file_2d_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '2D文件路径',
  `file_3d_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '3D文件路径',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_member_id` (`member_id`) USING BTREE,
  KEY `idx_material_id` (`material_id`) USING BTREE,
  KEY `idx_surface_treatment_id` (`surface_treatment_id`) USING BTREE,
  KEY `idx_heat_treatment_id` (`heat_treatment_id`) USING BTREE,
  KEY `idx_area_id` (`area_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='图纸报价表';
/*!40101 SET character_set_client = @saved_cs_client */;

