DROP TABLE IF EXISTS `fa_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fa_supplier` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录账号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录密码',
  `password_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密码明文',
  `equipment_type` int DEFAULT NULL,
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公司名称',
  `contact_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `area_id` int DEFAULT NULL COMMENT '区域ID',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '详细地址',
  `business_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '供应商类型:单一品种多批量,多品种小批量,混合',
  `main_industry` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '主要行业(JSON)',
  `customer_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户群体',
  `employee_count` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生产人数:20人以下,20-50人,50人以上',
  `annual_sales` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '年销售额:500万美金以下,500-1000万美金,1000万美金以上',
  `quality_dppm` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '质量DPPM:1000以下,1000-3000,3000以上',
  `delivery_rate` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '准时交货率:90-95%,95-98%,98%以上',
  `has_quality_manager` tinyint(1) DEFAULT '0' COMMENT '是否有质量经理和车间主任',
  `avg_delivery_days` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '平均交货周期:10天以内,10-20天,20天以上',
  `spare_capacity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '空余产能:40%以上,20-40%空余,20%以内空余',
  `has_three_coordinate` tinyint(1) DEFAULT '0' COMMENT '是否有三坐标',
  `has_top500_customers` tinyint(1) DEFAULT '0' COMMENT '是否有500强客户',
  `has_system` tinyint(1) DEFAULT '0' COMMENT '是否有MES/ERP等系统',
  `capability_score` int DEFAULT '0' COMMENT '综合能力得分',
  `industry_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '企业行业(JSON)',
  `material_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '擅长加工材料(JSON)',
  `process_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '加工类型(JSON)',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态:0=禁用,1=启用',
  `delete_time` timestamp NULL DEFAULT NULL COMMENT '删除时间',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
